body:
Netty version: 4.0.12.Final (but the suspected code is the same in the current 4.0 branch).

The SCTP_INIT_MAXSTREAMS property is ignored on NioSctpServerChannel (and judging by the source on OioSctpServerChannel too).

JUnit test to reproduce:

``` java
import com.sun.nio.sctp.SctpServerChannel;
import com.sun.nio.sctp.SctpStandardSocketOptions;
import io.netty.bootstrap.Bootstrap;
import io.netty.bootstrap.ServerBootstrap;
import io.netty.channel.ChannelHandler;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelOption;
import io.netty.channel.nio.NioEventLoopGroup;
import io.netty.channel.sctp.SctpChannel;
import io.netty.channel.sctp.SctpChannelOption;
import io.netty.channel.sctp.nio.NioSctpChannel;
import io.netty.channel.sctp.nio.NioSctpServerChannel;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

import java.lang.reflect.Method;
import java.net.InetSocketAddress;

public class SctpLimitStreamsTest {

    @Before
    public void setUp() {
        serverBootstrap = new ServerBootstrap();
        serverBootstrap.group(new NioEventLoopGroup(), new NioEventLoopGroup())
                .channel(NioSctpServerChannel.class)
                .option(ChannelOption.SO_REUSEADDR, true)
                .option(SctpChannelOption.SCTP_INIT_MAXSTREAMS, SctpStandardSocketOptions.InitMaxStreams.create(1, 1))
                .localAddress(new InetSocketAddress("localhost", 7766))
                .childHandler(new ChannelHandler() {
                    @Override
                    public void handlerAdded(ChannelHandlerContext ctx) throws Exception {

                    }

                    @Override
                    public void handlerRemoved(ChannelHandlerContext ctx) throws Exception {

                    }

                    @Override
                    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {

                    }
                });

        clientBootstrap = new Bootstrap()
                .group(new NioEventLoopGroup())
                .channel(NioSctpChannel.class)
                .option(SctpChannelOption.SCTP_INIT_MAXSTREAMS, SctpStandardSocketOptions.InitMaxStreams.create(112, 112))
                .handler(new ChannelHandler() {
                    @Override
                    public void handlerAdded(ChannelHandlerContext ctx) throws Exception {

                    }

                    @Override
                    public void handlerRemoved(ChannelHandlerContext ctx) throws Exception {

                    }

                    @Override
                    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {

                    }
                });

    }

    @After
    public void tearDown() {
        serverBootstrap.childGroup().shutdownGracefully();
        clientBootstrap.group().shutdownGracefully();
        serverBootstrap.group().shutdownGracefully().syncUninterruptibly(); // this sync is enough for this test
    }

    @Test
    public void testSctpInitMaxstreamsNetty() throws Exception {
        NioSctpServerChannel serverChannel = (NioSctpServerChannel) serverBootstrap.bind().syncUninterruptibly().channel();
        serverChannel.config().setOption(SctpChannelOption.SCTP_INIT_MAXSTREAMS, SctpStandardSocketOptions.InitMaxStreams.create(1, 1));

        SctpChannel clientChannel = (SctpChannel) clientBootstrap.connect(new InetSocketAddress("localhost", 7766)).syncUninterruptibly()
                .channel();

        System.out.println("maxOutboundStreams:" + clientChannel.association().maxOutboundStreams());
        System.out.println("maxInboundStreams:" + clientChannel.association().maxInboundStreams());
        assertEquals(1, clientChannel.association().maxOutboundStreams());
        assertEquals(1, clientChannel.association().maxInboundStreams());
    }

    @Test
    public void testSctpInitMaxstreamsNioDirect() throws Exception {
        NioSctpServerChannel serverChannel = (NioSctpServerChannel) serverBootstrap.bind().syncUninterruptibly().channel();

        Method getJavaChannel = serverChannel.getClass().getDeclaredMethod("javaChannel");
        getJavaChannel.setAccessible(true);
        SctpServerChannel javaChannel = (SctpServerChannel) getJavaChannel.invoke(serverChannel);
        javaChannel.setOption(SctpStandardSocketOptions.SCTP_INIT_MAXSTREAMS, SctpStandardSocketOptions.InitMaxStreams.create(1, 1));

        SctpChannel clientChannel = (SctpChannel) clientBootstrap.connect(new InetSocketAddress("localhost", 7766)).syncUninterruptibly()
                .channel();

        System.out.println("maxOutboundStreams:" + clientChannel.association().maxOutboundStreams());
        System.out.println("maxInboundStreams:" + clientChannel.association().maxInboundStreams());
        assertEquals(1, clientChannel.association().maxOutboundStreams());
        assertEquals(1, clientChannel.association().maxInboundStreams());
    }

    private ServerBootstrap serverBootstrap;
    private Bootstrap clientBootstrap;
}

```

The effect is that directly setting the SCTP_INIT_MAXSTREAMS on NIO SctpServerChannel in Testcase testSctpInitMaxstreamsNioDirect **succeeds**, 
while doing it using NETTY SctpChannel/ServerBootstrap in Testcase testSctpInitMaxstreamsNetty **fails**.

```
    [junit] Testcase: testSctpInitMaxstreamsNetty took 2.214 sec
    [junit]     FAILED
    [junit] expected:<1> but was:<112>
    [junit] junit.framework.AssertionFailedError: expected:<1> but was:<112>
    [junit]     at SctpLimitStreamsTest.testSctpInitMaxstreamsNetty(SctpLimitStreamsTest.java:90)
```

It seems that the offending code is located in io.netty.channel.sctp.DefaultSctpServerChannelConfig.setOption(...):

``` java

import static com.sun.nio.sctp.SctpStandardSocketOptions.*; 
//                   /\== note that the static import is "com.sun.nio" 

...

@Override
    public <T> boolean setOption(ChannelOption<T> option, T value) {
        validate(option, value);

        if (option == ChannelOption.SO_RCVBUF) {
            setReceiveBufferSize((Integer) value);
        } else if (option == ChannelOption.SO_SNDBUF) {
            setSendBufferSize((Integer) value);
        } else if (option == SCTP_INIT_MAXSTREAMS) {  
// YOU SHALL NOT PASS...
// as in the preceding conditional we are comparing 
// constant from io.netty.channel.ChannelOption WITH constant from 
// com.sun.nio.sctp.SctpStandardSocketOptions
// (option == SCTP_INIT_MAXSTREAMS) is always FALSE
            setInitMaxStreams((InitMaxStreams) value);
        } else {
            return super.setOption(option, value);
        }

        return true;
    }

```

Environment:
java version "1.7.0_72"
Java(TM) SE Runtime Environment (build 1.7.0_72-b14)
Java HotSpot(TM) 64-Bit Server VM (build 24.72-b04, mixed mode)

